func startedCanary(t *testing.T, units []Unit) (Record, time.Time) {
	t.Helper()
	record := newRecord(t, units, testPolicy())
	record = apply(t, record, Event{Kind: EventStart, At: testStart})
	record = apply(t, record, Event{Kind: EventPreflightPassed, At: testStart})
	return record, testStart
}

func requireRollingBack(t *testing.T, record Record, reason string) {
	t.Helper()
	if record.Phase != PhaseRollingBack || !slices.Contains(record.KnownBad, toDigest) || !strings.Contains(record.Reason, reason) {
		t.Fatalf("phase=%s known_bad=%v reason=%q; want rolling-back with %q", record.Phase, record.KnownBad, record.Reason, reason)
	}
	for _, action := range NextActions(record) {
		if action.Kind != ActionRollback || action.Digest != fromDigest {
			t.Fatalf("rollback emitted %+v", action)
		}
	}
}

store_reads.text:
func (state CellState) validate(cell string) error {
	if state.SchemaVersion != SchemaVersion || state.Cell != cell ||
		state.ActiveRolloutID != "" && !entityid.Valid(state.ActiveRolloutID) ||
		len(state.KnownBad) > MaxKnownBad || len(state.Attempts) > maxAttemptDigest {
		return fmt.Errorf("%w: cell rollout state", ErrInvalid)
	}
	for _, digest := range state.KnownBad {
		if !digestRE.MatchString(digest) {
			return fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
	}
	return nil
}

// Store persists rollout records with CAS on the KV revision. Every write is
// preceded by an authority Guard for the record's epoch (invariant b).
// Records decode tolerantly, so an older controller reads a newer one's
// records during a self-update; schema_version names breaking changes.
type Store struct {
	// Admission and publication share the lifetime of a reservation's generation proof.
	mu     sync.Mutex
	kv     jetstream.KeyValue
	fencer authority.Fencer
	cell   string
}

// OpenStore provisions or binds the rollout bucket for one cell.
func OpenStore(ctx context.Context, js jetstream.JetStream, cell string, replicas int, fencer authority.Fencer) (*Store, error) {
	if js == nil || fencer == nil || !tokenRE.MatchString(cell) || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: rollout store configuration", ErrInvalid)
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: Bucket, Storage: jetstream.FileStorage, Replicas: replicas, History: 8, MaxValueSize: maxRecordBytes,
	})
	if err != nil {
		return nil, fmt.Errorf("rollout store: %w", err)
	}
	return &Store{kv: kv, fencer: fencer, cell: cell}, nil
}

func rolloutKey(id string) string { return id }

// knownBadKey holds one durable known-bad record. The cell's KnownBad list is
// bounded and ages out its oldest entries; these per-digest records do not,
// so a rejected digest never becomes eligible again without a reviewed
// removal of its record.
func knownBadKey(digest string) string { return "knownbad." + digest }

type knownBadEntry struct {
	Digest string `json:"digest"`
}

// recordKnownBad durably records digest. It is idempotent.
func (s *Store) recordKnownBad(ctx context.Context, epoch uint64, digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: known-bad digest", ErrInvalid)
	}
	encoded, err := protocol.EncodeJSON(knownBadEntry{Digest: digest})
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if _, err := s.kv.Create(ctx, knownBadKey(digest), encoded); err != nil && !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("record known-bad digest: %w", err)
	}
	return nil
}

// knownBad reports whether digest is known bad in the cell list or in its
// durable per-digest record.
func (s *Store) knownBad(ctx context.Context, state CellState, digest string) (bool, error) {
	if slices.Contains(state.KnownBad, digest) {
		return true, nil
	}
	_, err := s.kv.Get(ctx, knownBadKey(digest))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("read known-bad digest: %w", err)
	}
	return true, nil
}

// Cell returns the cell slot and its revision (zero when absent).
func (s *Store) Cell(ctx context.Context) (CellState, uint64, error) {
	entry, err := s.kv.Get(ctx, cellKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return CellState{SchemaVersion: SchemaVersion, Cell: s.cell}, 0, nil
	}
	if err != nil {
		return CellState{}, 0, err
	}
	var state CellState
	if err := protocol.DecodeTolerant(entry.Value(), &state, maxRecordBytes); err != nil {
		return CellState{}, 0, err
	}
	if err := state.validate(s.cell); err != nil {
		return CellState{}, 0, err
	}
	return state, entry.Revision(), nil
}

// Load returns a rollout record and its KV revision.
func (s *Store) Load(ctx context.Context, rolloutID string) (Record, uint64, error) {
	if !entityid.Valid(rolloutID) {
		return Record{}, 0, fmt.Errorf("%w: rollout ID", ErrInvalid)
	}
	entry, err := s.kv.Get(ctx, rolloutKey(rolloutID))
	if err != nil {
		return Record{}, 0, err
	}
	// Records decode tolerantly, so a marker would decode as an empty record:
	// read it first. A record always has a schema version and a marker never
	// does, so a newer binary's members change neither.
	if marker, err := decodeAbandoned(entry.Value(), rolloutID); err != nil {
		return Record{}, 0, err
	} else if marker != nil {
		return Record{}, 0, marker
	}
	var record Record
	if err := protocol.DecodeTolerant(entry.Value(), &record, maxRecordBytes); err != nil {
		return Record{}, 0, err
	}
	if err := record.Validate(); err != nil {
		return Record{}, 0, err
	}
	if record.Cell != s.cell || record.RolloutID != rolloutID {
		return Record{}, 0, fmt.Errorf("%w: stored rollout scope", ErrInvalid)
	}
	return record, entry.Revision(), nil
}

admission.text:
func (s *Store) Begin(ctx context.Context, spec Spec, now time.Time) (Record, uint64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if spec.Cell != s.cell {
		return Record{}, 0, fmt.Errorf("%w: rollout cell", ErrInvalid)
	}
	if err := s.fencer.Guard(ctx, spec.AuthorityEpoch); err != nil {
		return Record{}, 0, err
	}
	// An ID already bound to another rollout is refused before the cell
	// slot is reserved or the target's attempt is counted.
	bound := false
	if existing, _, err := s.Load(ctx, spec.RolloutID); err == nil {
		if err := sameRollout(existing, spec); err != nil {
			return Record{}, 0, err
		}
		bound = true
	} else if errors.Is(err, ErrAbandonedRollout) {
		if err := s.releaseSlot(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
			return Record{}, 0, err
		}
		return Record{}, 0, ErrAbandonedRollout
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, err
	}
	if !bound {
		if release, kind, found, err := s.releaseStage(ctx, spec.RolloutID); err != nil {
			return Record{}, 0, err
		} else if found && (spec.ToDigest != release.Digest || spec.Kind != kind ||
			!spec.StartedAt.IsZero() && !spec.StartedAt.Equal(release.CreatedAt)) {
			return Record{}, 0, fmt.Errorf("%w: release stage binding", ErrConflict)
		} else if found {
			spec.StartedAt = release.CreatedAt
			bound = true
		}
	}
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return Record{}, 0, err
		}
		if state.ActiveRolloutID == spec.RolloutID {
			// Only an existing immutable record can resume the same ID.
			if _, _, err := s.Load(ctx, spec.RolloutID); errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, ErrAbandonedRollout) {
				if err := s.abandon(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
					return Record{}, 0, err
				}
				if err := s.releaseSlot(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
					return Record{}, 0, err
				}
				return Record{}, 0, ErrAbandonedRollout
			} else if err != nil {
				return Record{}, 0, err
			}
			return s.createRecord(ctx, spec, state, now)
		}
		if state.ActiveRolloutID != "" {
			// A terminal commit whose cell release was interrupted is
			// repaired here; a live rollout keeps the slot.
			active, _, err := s.Load(ctx, state.ActiveRolloutID)
			if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, ErrAbandonedRollout) {
				// The slot was claimed but its record was never created (a
				// crash or failure between the two writes). Abandon the ID
				// so a late create of it fails, then release the slot.
				if err := s.abandon(ctx, spec.AuthorityEpoch, state.ActiveRolloutID); err != nil {
					return Record{}, 0, err
				}
				if err := s.releaseSlot(ctx, spec.AuthorityEpoch, state.ActiveRolloutID); err != nil {
					return Record{}, 0, err
				}
				continue
			}
			if err != nil {
				return Record{}, 0, fmt.Errorf("load active rollout %q: %w", state.ActiveRolloutID, err)
			}
			if !active.Phase.Terminal() {
				return Record{}, 0, ErrActiveRollout
			}
			if err := s.syncCell(ctx, withEpoch(active, spec.AuthorityEpoch)); err != nil {
				return Record{}, 0, err
			}
			continue
		}
		if !bound {
			return Record{}, 0, fmt.Errorf("%w: rollout needs a published release stage", ErrNoRelease)
		}
		if bad, err := s.knownBad(ctx, state, spec.ToDigest); err != nil {
			return Record{}, 0, err
		} else if bad {
			return Record{}, 0, ErrKnownBad
		}
		if bad, err := s.knownBad(ctx, state, spec.FromDigest); err != nil {
			return Record{}, 0, err
		} else if bad {
			return Record{}, 0, fmt.Errorf("%w: rollback target digest is known bad", ErrInvalid)
		}
		maxAttempts := spec.Policy.MaxAttempts
		if state.Attempts[spec.ToDigest] >= maxAttempts {
			return Record{}, 0, ErrAttemptsExhausted
		}
		if _, err := New(withKnownBad(spec, state.KnownBad), now); err != nil {
			return Record{}, 0, err
		}
		next := state
		next.ActiveRolloutID = spec.RolloutID
		next.Attempts = make(map[string]int, len(state.Attempts)+1)
		for digest, count := range state.Attempts {
			next.Attempts[digest] = count
		}
		next.Attempts[spec.ToDigest]++
		boundAttempts(next.Attempts, next.KnownBad, spec.ToDigest)
		if err := s.writeCell(ctx, spec.AuthorityEpoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Record{}, 0, err
		}
		return s.createRecord(ctx, spec, next, now)
	}
	return Record{}, 0, ErrConflict
}

// sameRollout reports whether an existing record is the rollout spec
// describes. A retry must describe the same plan, not only the same target:
// a changed unit set or policy would otherwise silently run the stored,
// older plan.
func sameRollout(existing Record, spec Spec) error {
	if existing.FromDigest != spec.FromDigest || existing.ToDigest != spec.ToDigest || existing.Kind != spec.Kind {
		return fmt.Errorf("%w: rollout ID is bound to a different rollout", ErrConflict)
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return err
	}
	if existing.PolicyDigest != policyDigest || !slices.EqualFunc(existing.Waves, waves, slices.Equal) ||
		!spec.StartedAt.IsZero() && !existing.StartedAt.Equal(spec.StartedAt) {
		return fmt.Errorf("%w: rollout ID is bound to a different plan", ErrConflict)
	}
	return nil
}

func withKnownBad(spec Spec, knownBad []string) Spec {
	spec.KnownBad = append(slices.Clone(spec.KnownBad), knownBad...)
	return spec
}

func (s *Store) createRecord(ctx context.Context, spec Spec, state CellState, now time.Time) (Record, uint64, error) {
	if existing, revision, err := s.Load(ctx, spec.RolloutID); err == nil {
		if err := sameRollout(existing, spec); err != nil {
			return Record{}, 0, err
		}
		return existing, revision, nil
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, err
	}
	record, err := New(withKnownBad(spec, state.KnownBad), now)
	if err != nil {
		return Record{}, 0, err
	}
	encoded, err := protocol.EncodeJSON(record)
	if err != nil {
		return Record{}, 0, err
	}
	if err := s.fencer.Guard(ctx, record.AuthorityEpoch); err != nil {
		return Record{}, 0, err
	}
	revision, err := s.kv.Create(ctx, rolloutKey(record.RolloutID), encoded)
	if errors.Is(err, jetstream.ErrKeyExists) {
		return s.createRecord(ctx, spec, state, now)
	}
	if err != nil {
		return Record{}, 0, err
	}
	recordAdmitted(ctx, record)
	return record, revision, nil
}

commit.text:
func (s *Store) Commit(ctx context.Context, revision uint64, next Record) (uint64, error) {
	if err := next.Validate(); err != nil {
		return 0, err
	}
	current, storedRevision, err := s.Load(ctx, next.RolloutID)
	if err != nil {
		return 0, err
	}
	if storedRevision != revision {
		return 0, ErrConflict
	}
	if current.AuthorityEpoch != next.AuthorityEpoch {
		return 0, ErrFenced
	}
	if current.Kind != next.Kind || current.Cell != next.Cell || current.FromDigest != next.FromDigest || current.ToDigest != next.ToDigest ||
		current.PolicyDigest != next.PolicyDigest || !slices.EqualFunc(current.Waves, next.Waves, slices.Equal) ||
		!current.StartedAt.Equal(next.StartedAt) {
		return 0, fmt.Errorf("%w: immutable rollout fields changed", ErrInvalid)
	}
	if current.Phase.Terminal() {
		return 0, ErrTerminal
	}
	encoded, err := protocol.EncodeJSON(next)
	if err != nil {
		return 0, err
	}
	if err := s.fencer.Guard(ctx, next.AuthorityEpoch); err != nil {
		return 0, err
	}
	newRevision, err := s.kv.Update(ctx, rolloutKey(next.RolloutID), encoded, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return 0, ErrConflict
	}
	if err != nil {
		return 0, err
	}
	recordTransition(ctx, current, next)
	if err := s.syncCell(ctx, next); err != nil {
		return newRevision, fmt.Errorf("record committed; cell slot update pending: %w", err)
	}
	return newRevision, nil
}

slot_write.text:
func (s *Store) syncCell(ctx context.Context, record Record) error {
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return err
		}
		next := state
		next.KnownBad = slices.Clone(state.KnownBad)
		for _, digest := range record.KnownBad {
			if !slices.Contains(next.KnownBad, digest) {
				// Durable first: the cell list below is only a bounded
				// cache of the per-digest records.
				if err := s.recordKnownBad(ctx, record.AuthorityEpoch, digest); err != nil {
					return err
				}
				next.KnownBad = append(next.KnownBad, digest)
			}
		}
		// The list keeps insertion order; the oldest entries age out first.
		// Every entry that ages out keeps its durable record, including
		// entries listed before durable records existed.
		if len(next.KnownBad) > MaxKnownBad {
			for _, digest := range next.KnownBad[:len(next.KnownBad)-MaxKnownBad] {
				if err := s.recordKnownBad(ctx, record.AuthorityEpoch, digest); err != nil {
					return err
				}
			}
			next.KnownBad = next.KnownBad[len(next.KnownBad)-MaxKnownBad:]
		}
		next.Attempts = maps.Clone(state.Attempts)
		if record.Phase.Terminal() && state.ActiveRolloutID == record.RolloutID {
			next.ActiveRolloutID = ""
			// The attempt budget limits retries of a rejected digest. A
			// completed rollout proved its digest; an untouched abort never
			// tried it. Refund once as the slot is released so either can retry.
			if (record.Phase == PhaseComplete || record.abortedBeforeUpdate()) && state.Attempts[record.ToDigest] > 0 {
				if next.Attempts[record.ToDigest]--; next.Attempts[record.ToDigest] == 0 {
					delete(next.Attempts, record.ToDigest)
				}
			}
		}
		boundAttempts(next.Attempts, next.KnownBad, "")
		if slices.Equal(next.KnownBad, state.KnownBad) && next.ActiveRolloutID == state.ActiveRolloutID &&
			maps.Equal(next.Attempts, state.Attempts) {
			return nil
		}
		if err := s.writeCell(ctx, record.AuthorityEpoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else {
			return err
		}
	}
	return ErrConflict
}

func (s *Store) writeCell(ctx context.Context, epoch uint64, state CellState, revision uint64) error {
	if err := state.validate(s.cell); err != nil {
		return err
	}
	encoded, err := protocol.EncodeJSON(state)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if revision == 0 {
		_, err = s.kv.Create(ctx, cellKey, encoded)
	} else {
		_, err = s.kv.Update(ctx, cellKey, encoded, revision)
	}
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return ErrConflict
	}
	return err
}

abandonment.text:
func decodeAbandoned(wire []byte, rolloutID string) (*abandonedMarker, error) {
	var kind struct {
		AbandonedRollout string `json:"abandoned_rollout"`
		SchemaVersion    int    `json:"schema_version"`
	}
	if err := protocol.DecodeTolerant(wire, &kind, maxRecordBytes); err != nil {
		return nil, err
	}
	if kind.AbandonedRollout == "" || kind.SchemaVersion != 0 {
		return nil, nil
	}
	var marker abandonedMarker
	if err := protocol.DecodeStrict(wire, &marker, maxRecordBytes); err != nil {
		return nil, err
	}
	if marker.AbandonedRollout != rolloutID || !entityid.Valid(rolloutID) {
		return nil, fmt.Errorf("%w: abandoned rollout binding", ErrInvalid)
	}
	return &marker, nil
}

// abandon writes the marker for rolloutID unless a record or marker exists.
func (s *Store) abandon(ctx context.Context, epoch uint64, rolloutID string) error {
	encoded, err := protocol.EncodeJSON(abandonedMarker{AbandonedRollout: rolloutID})
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = s.kv.Create(ctx, rolloutKey(rolloutID), encoded)
	if errors.Is(err, jetstream.ErrKeyExists) {
		// A concurrent create won or the marker is already in place; the
		// next Load tells which.
		if _, _, loadErr := s.Load(ctx, rolloutID); loadErr == nil {
			return ErrActiveRollout
		} else if !errors.Is(loadErr, ErrAbandonedRollout) {
			return loadErr
		}
		return nil
	}
	return err
}

// releaseSlot refunds a proven release reservation once, in the CAS that clears it.
func (s *Store) releaseSlot(ctx context.Context, epoch uint64, rolloutID string) error {
	for range cellCASAttempts {
		state, revision, err := s.Cell(ctx)
		if err != nil {
			return err
		}
		if state.ActiveRolloutID != rolloutID {
			return nil
		}
		if _, _, err := s.Load(ctx, rolloutID); !errors.Is(err, ErrAbandonedRollout) {
			if err != nil {
				return err
			}
			return ErrActiveRollout
		}
		release, _, found, err := s.releaseStage(ctx, rolloutID)
		if err != nil {
			return err
		}
		next := state
		next.ActiveRolloutID = ""
		next.Attempts = maps.Clone(state.Attempts)
		// An arbitrary orphan ID proves no target; never guess from historical counts.
		if found && next.Attempts[release.Digest] > 0 {
			if next.Attempts[release.Digest]--; next.Attempts[release.Digest] == 0 {
				delete(next.Attempts, release.Digest)
			}
		}
		if err := s.writeCell(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else {
			return err
		}
	}
	return ErrConflict
}

active.text:
func (s *Store) IsKnownBad(ctx context.Context, digest string) (bool, error) {
	if !digestRE.MatchString(digest) {
		return false, fmt.Errorf("%w: known-bad digest", ErrInvalid)
	}
	state, _, err := s.Cell(ctx)
	if err != nil {
		return false, err
	}
	return s.knownBad(ctx, state, digest)
}

// Active returns the record that holds the cell's rollout slot and its KV
// revision. ok is false when the slot is free or names a claim whose record
// was never created; Begin repairs such a slot.
func (s *Store) Active(ctx context.Context) (record Record, revision uint64, ok bool, err error) {
	state, _, err := s.Cell(ctx)
	if err != nil || state.ActiveRolloutID == "" {
		return Record{}, 0, false, err
	}
	record, revision, err = s.Load(ctx, state.ActiveRolloutID)
	if errors.Is(err, ErrAbandonedRollout) {
		return Record{}, 0, false, nil
	}
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, false, nil
	}
	if err != nil {
		return Record{}, 0, false, err
	}
	return record, revision, true, nil
}

// RecoverReservation abandons a record-free slot before program planning, including a marker-before-clear crash.
func (s *Store) RecoverReservation(ctx context.Context, epoch uint64) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, _, err := s.Cell(ctx)
	if err != nil || state.ActiveRolloutID == "" {
		return err
	}
	if _, _, err := s.Load(ctx, state.ActiveRolloutID); !errors.Is(err, jetstream.ErrKeyNotFound) && !errors.Is(err, ErrAbandonedRollout) {
		return err
	}
	if err := s.abandon(ctx, epoch, state.ActiveRolloutID); err != nil {
		return err
	}
	return s.releaseSlot(ctx, epoch, state.ActiveRolloutID)
}

// Settle releases the cell slot still held by a terminal record whose
// release was interrupted after its commit, fenced by the caller's epoch.
// It is a no-op for an active record.
func (s *Store) Settle(ctx context.Context, record Record, epoch uint64) error {
	if !record.Phase.Terminal() {
		return nil
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	return s.syncCell(ctx, withEpoch(record, epoch))
}

release_reads.text:
func generationKey(cell string, generation uint64) string {
	return entityid.Derive("release", cell, strconv.FormatUint(generation, 10))
}

// ReleaseRolloutID is the rollout ID prefix of a desired release generation.
func ReleaseRolloutID(generation uint64) string {
	return entityid.Derive("release-rollout", strconv.FormatUint(generation, 10))
}

// releaseStage resolves derived stage IDs before reading their immutable generation.
func (s *Store) releaseStage(ctx context.Context, id string) (Release, Kind, bool, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return Release{}, "", false, err
	}
	// Derivation keeps network reads independent of permanent operational history.
	// shortcut: historical IDs cost local hashing; index them if generation counts make that costly.
	for generation := desired.Generation(); generation > 0; generation-- {
		if err := ctx.Err(); err != nil {
			return Release{}, "", false, err
		}
		rolloutID := ReleaseRolloutID(generation)
		for _, stage := range []struct {
			domain string
			kind   Kind
		}{{ControllerReleaseDomain, KindController}, {HostReleaseDomain, KindHost}} {
			if id != entityid.Derive(stage.domain, rolloutID) {
				continue
			}
			release, err := s.generation(ctx, desired, generation)
			if errors.Is(err, ErrNoRelease) {
				return Release{}, "", false, nil
			}
			if err != nil {
				return Release{}, "", false, err
			}
			if release.ID != generationKey(s.cell, generation) {
				return Release{}, "", false, fmt.Errorf("%w: release stage generation ID", ErrInvalid)
			}
			return release, stage.kind, true, nil
		}
	}
	return Release{}, "", false, ctx.Err()
}

// Release is one generation of the cell's desired orchestrator binary.
// Receipt and Delegation are the release receipt the steps carry, so a node
// can restage the binary; nodes verify them against their own roots.
// SourceRevision and RunNumber are what the verified receipt names (the run
// only for an update receipt signed after CI qualified it), so a release
// channel can refuse a run older than the cell's newest. RollbackOf names
// the earlier generation a rollback repeats.
type Release struct {
	ReleaseSequence         uint64    `json:"release_sequence,omitzero"`
	SequenceMigration       []byte    `json:"sequence_migration,omitempty"`
	SequenceMigrationSHA256 string    `json:"sequence_migration_sha256,omitempty"`
	ID                      string    `json:"id"`
	Generation              uint64    `json:"generation"`
	Digest                  string    `json:"digest"`
	SourceRevision          string    `json:"source_revision,omitempty"`
	RunNumber               int64     `json:"run_number,omitzero"`
	Receipt                 []byte    `json:"receipt,omitempty"`
	Delegation              []byte    `json:"delegation,omitempty"`
	RollbackOf              uint64    `json:"rollback_of,omitzero"`
	Actor                   string    `json:"actor"`
	CreatedAt               time.Time `json:"created_at"`
}

func (r Release) validate() error {
	if r.ReleaseSequence == 0 && (len(r.SequenceMigration) > 0 || r.SequenceMigrationSHA256 != "") || r.ReleaseSequence > 0 && (len(r.SequenceMigration) == 0 || !digestRE.MatchString(r.SequenceMigrationSHA256) || len(r.Receipt) == 0 || len(r.Delegation) == 0) || len(r.SequenceMigration) > maxReleaseWire {
		return fmt.Errorf("%w: release sequence metadata", ErrInvalid)
	}
	if !entityid.Valid(r.ID) || r.Generation == 0 || !digestRE.MatchString(r.Digest) || r.RunNumber < 0 ||
		r.SourceRevision != "" && !release.ValidSourceRevision(r.SourceRevision) ||
		len(r.Receipt) > maxReleaseWire || len(r.Delegation) > maxReleaseWire ||
		len(r.Delegation) > 0 && len(r.Receipt) == 0 || r.RollbackOf >= r.Generation ||
		(!tokenRE.MatchString(r.Actor) && !entityid.Valid(r.Actor)) || r.CreatedAt.IsZero() {
		return fmt.Errorf("%w: release generation", ErrInvalid)
	}
	return nil
}

// Desired is the cell's newest release generation. Paused stops the executor
// from starting another rollout; a rollout already running still finishes.
type Desired struct {
	OrderingFloor       Release `json:"ordering_floor,omitzero"`
	LegacyFloor         Release `json:"legacy_floor,omitzero"`
	LegacyIssuanceFloor Release `json:"legacy_issuance_floor,omitzero"`
	SchemaVersion       int     `json:"schema_version"`
	Cell                string  `json:"cell"`
	Release             Release `json:"release,omitzero"`
	Paused              bool    `json:"paused,omitzero"`
}

// Generation is the newest generation, zero before the first release.
func (d Desired) Generation() uint64 { return d.Release.Generation }

func (d Desired) validate(cell string) error {
	if (d.SchemaVersion != SchemaVersion && d.SchemaVersion != DesiredSchemaVersion) || d.Cell != cell {
		return fmt.Errorf("%w: desired release", ErrInvalid)
	}
	if d.SchemaVersion == SchemaVersion && (d.OrderingFloor.Generation != 0 || d.LegacyFloor.Generation != 0 || d.LegacyIssuanceFloor.Generation != 0 || d.Release.ReleaseSequence != 0) {
		return fmt.Errorf("%w: legacy desired schema carries sequence state", ErrInvalid)
	}
	if d.OrderingFloor.Generation > 0 {
		if err := d.OrderingFloor.validate(); err != nil {
			return err
		}
		if d.OrderingFloor.ReleaseSequence == 0 {
			return fmt.Errorf("%w: ordering floor", ErrInvalid)
		}
	}
	for _, floor := range []Release{d.LegacyFloor, d.LegacyIssuanceFloor} {
		if floor.Generation > 0 {
			if err := floor.validate(); err != nil {
				return err
			}
			if floor.ReleaseSequence != 0 {
				return fmt.Errorf("%w: legacy ordering floor", ErrInvalid)
			}
		}
	}
	if d.Release.Generation != 0 {
		if d.Release.ReleaseSequence > d.OrderingFloor.ReleaseSequence {
			return fmt.Errorf("%w: desired exceeds retained ordering floor", ErrInvalid)
		}
		return d.Release.validate()
	}
	return nil
}

// Desired returns the record and its revision (zero when absent).
func (s *Store) Desired(ctx context.Context) (Desired, uint64, error) {
	entry, err := s.kv.Get(ctx, desiredKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Desired{SchemaVersion: DesiredSchemaVersion, Cell: s.cell}, 0, nil
	}
	if err != nil {
		return Desired{}, 0, err
	}
	var desired Desired
	if err := protocol.DecodeTolerant(entry.Value(), &desired, maxRecordBytes); err != nil {
		return Desired{}, 0, err
	}
	if err := desired.validate(s.cell); err != nil {
		return Desired{}, 0, err
	}
	return desired, entry.Revision(), nil
}

// ReleaseGeneration returns one retained generation.
func (s *Store) ReleaseGeneration(ctx context.Context, generation uint64) (Release, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return Release{}, err
	}
	return s.generation(ctx, desired, generation)
}

// generation reads a retained copy. The copy has no schema version of its
// own: the desired record's, which every caller has validated, covers it. A
// breaking Release change raises DesiredSchemaVersion, so an older controller
// refuses the desired record and never reads a newer generation it would
// misread; a newer binary's added members are skipped, as in the desired
// record itself.
func (s *Store) generation(ctx context.Context, desired Desired, generation uint64) (Release, error) {
	if generation != 0 && generation == desired.Generation() {
		return desired.Release, nil
	}
	if generation == 0 || generation > desired.Generation() {
		return Release{}, fmt.Errorf("%w: %d", ErrNoRelease, generation)
	}
	entry, err := s.kv.Get(ctx, generationKey(s.cell, generation))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Release{}, fmt.Errorf("%w: %d is no longer retained", ErrNoRelease, generation)
	}
	if err != nil {
		return Release{}, err
	}
	var release Release
	if err := protocol.DecodeTolerant(entry.Value(), &release, maxRecordBytes); err != nil {
		return Release{}, err
	}
	if err := release.validate(); err != nil || release.Generation != generation || release.ID != generationKey(s.cell, generation) {
		return Release{}, fmt.Errorf("%w: stored generation %d", ErrInvalid, generation)
	}
	return release, nil
}

release_writes.text:
func (s *Store) PublishRelease(ctx context.Context, epoch uint64, release Release) (Release, error) {
	if release.ReleaseSequence > 0 || len(release.SequenceMigration) > 0 || release.SequenceMigrationSHA256 != "" || release.RollbackOf != 0 {
		return Release{}, fmt.Errorf("%w: sequenced releases require signature admission; rollbacks require retained generation", ErrInvalid)
	}
	if err := rejectSequencedReceipt(release.Receipt); err != nil {
		return Release{}, err
	}
	return s.publishRelease(ctx, epoch, release, false)
}

func (s *Store) publishRelease(ctx context.Context, epoch uint64, release Release, rollback bool) (Release, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if bad, err := s.IsKnownBad(ctx, release.Digest); err != nil {
		return Release{}, err
	} else if bad {
		return Release{}, ErrKnownBad
	}
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return Release{}, err
		}
		seeded, err := s.seedReleaseOrdering(ctx, desired)
		if err != nil {
			return Release{}, err
		}
		next := seeded
		normalized := release
		normalized.Generation = desired.Generation() + 1
		normalized.ID = generationKey(s.cell, normalized.Generation)
		normalized.CreatedAt = release.CreatedAt.UTC()
		if err := normalized.validate(); err != nil {
			return Release{}, err
		}
		if !rollback {
			if err := advanceReleaseOrdering(&next, normalized, s.cell); err != nil {
				return Release{}, err
			}
		}
		if desired.Generation() > 0 && desired.Release.Digest == release.Digest {
			retry, err := s.retryUntouchedRelease(ctx, desired.Release, release)
			if err != nil {
				return Release{}, err
			}
			if !retry {
				if desired.SchemaVersion != DesiredSchemaVersion || desired.OrderingFloor.ReleaseSequence != next.OrderingFloor.ReleaseSequence || desired.LegacyFloor.Generation != next.LegacyFloor.Generation || desired.LegacyIssuanceFloor.Generation != next.LegacyIssuanceFloor.Generation {
					if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
						continue
					} else if err != nil {
						return Release{}, err
					}
				}
				return desired.Release, ErrReleaseUnchanged
			}
		}
		next.Release = normalized
		next.SchemaVersion = DesiredSchemaVersion
		if err := next.validate(s.cell); err != nil {
			return Release{}, err
		}
		// The generation being replaced is retained before the record
		// moves; a copy lost to a crash is written again by the next
		// publish, since the record still holds it.
		if desired.Generation() > 0 {
			if err := s.retain(ctx, epoch, desired.Release); err != nil {
				return Release{}, err
			}
		}
		if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Release{}, err
		}
		if newest := next.Generation(); newest > ReleaseHistory {
			// Best effort: a missed purge only keeps one more old copy.
			oldest := newest - ReleaseHistory
			state, _, err := s.Cell(ctx)
			if err == nil && state.ActiveRolloutID != entityid.Derive(ControllerReleaseDomain, ReleaseRolloutID(oldest)) &&
				state.ActiveRolloutID != entityid.Derive(HostReleaseDomain, ReleaseRolloutID(oldest)) && s.fencer.Guard(ctx, epoch) == nil {
				_ = s.kv.Purge(ctx, generationKey(s.cell, oldest))
			}
		}
		return next.Release, nil
	}
	return Release{}, ErrConflict
}

func (s *Store) retryUntouchedRelease(ctx context.Context, previous, next Release) (bool, error) {
	if previous.RollbackOf != 0 || next.RollbackOf != 0 || !newerReleaseOrder(previous, next) || next.ReleaseSequence == 0 && !next.CreatedAt.After(previous.CreatedAt) {
		return false, nil
	}
	aborted := false
	for _, domain := range []string{ControllerReleaseDomain, HostReleaseDomain} {
		record, _, err := s.Load(ctx, entityid.Derive(domain, ReleaseRolloutID(previous.Generation)))
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			continue
		}
		if errors.Is(err, ErrAbandonedRollout) {
			aborted = true
			continue
		}
		if err != nil || !record.abortedBeforeUpdate() {
			return false, err
		}
		kind := KindController
		if domain == HostReleaseDomain {
			kind = KindHost
		}
		if record.ToDigest != previous.Digest || record.Kind != kind || !record.StartedAt.Equal(previous.CreatedAt) {
			return false, fmt.Errorf("%w: aborted release stage binding", ErrInvalid)
		}
		aborted = true
	}
	return aborted, nil
}

func (s *Store) retain(ctx context.Context, epoch uint64, release Release) error {
	encoded, err := protocol.EncodeJSON(release)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if _, err := s.kv.Put(ctx, generationKey(s.cell, release.Generation), encoded); err != nil {
		return fmt.Errorf("retain release generation: %w", err)
	}
	return nil
}

// RollbackRelease publishes a new generation that repeats generation to.
// History is never rewritten: a rollback is itself a generation, so a later
// one can roll it back again.
func (s *Store) RollbackRelease(ctx context.Context, epoch, to uint64, actor string, now time.Time) (Release, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return Release{}, err
	}
	if to == 0 || to >= desired.Generation() {
		return Release{}, fmt.Errorf("%w: roll back to a generation before %d", ErrInvalid, desired.Generation())
	}
	target, err := s.generation(ctx, desired, to)
	if err != nil {
		return Release{}, err
	}
	repeat := target
	repeat.RollbackOf, repeat.Actor, repeat.CreatedAt = to, actor, now
	return s.publishRelease(ctx, epoch, repeat, true)
}

// PauseReleases sets the cell's pause, fenced by epoch.
func (s *Store) PauseReleases(ctx context.Context, epoch uint64, paused bool) (Desired, error) {
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return Desired{}, err
		}
		if desired.Paused == paused {
			return desired, nil
		}
		desired.Paused = paused
		if err := s.writeDesired(ctx, epoch, desired, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Desired{}, err
		}
		return desired, nil
	}
	return Desired{}, ErrConflict
}

func (s *Store) writeDesired(ctx context.Context, epoch uint64, desired Desired, revision uint64) error {
	desired.SchemaVersion = DesiredSchemaVersion
	if err := desired.validate(s.cell); err != nil {
		return err
	}
	encoded, err := protocol.EncodeJSON(desired)
	if err != nil {
		return err
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	if revision == 0 {
		_, err = s.kv.Create(ctx, desiredKey, encoded)
	} else {
		_, err = s.kv.Update(ctx, desiredKey, encoded, revision)
	}
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return ErrConflict
	}
	return err
}

pin_inventory.text:
func (s *Store) Releases(ctx context.Context, limit int) ([]Release, error) {
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return nil, err
	}
	var releases []Release
	newest := desired.Generation()
	for generation := newest; generation > 0 && len(releases) < limit && newest-generation < ReleaseHistory; generation-- {
		release, err := s.generation(ctx, desired, generation)
		if errors.Is(err, ErrNoRelease) {
			continue
		}
		if err != nil {
			return nil, err
		}
		releases = append(releases, release)
	}
	return releases, nil
}

// retainedReleases inventories every readable generation, including copies left by failed purges.
func (s *Store) retainedReleases(ctx context.Context, desired Desired) ([]Release, error) {
	var releases []Release
	if desired.Generation() > 0 {
		releases = append(releases, desired.Release)
	}
	// Failed best-effort purges leave readable rollback targets beyond ReleaseHistory.
	keys, err := releasechannel.PinKeys(ctx, s.kv, ">")
	if err != nil {
		return nil, err
	}
	for _, key := range keys {
		if key == cellKey || key == desiredKey || strings.HasPrefix(key, "knownbad.") {
			continue
		}
		if !entityid.Valid(key) {
			return nil, fmt.Errorf("%w: retained record key %q", ErrInvalid, key)
		}
		entry, err := s.kv.Get(ctx, key)
		if err != nil {
			return nil, err
		}
		// Operational records share the entity-key namespace with retained releases.
		var kind struct {
			HostMembership
			SchemaVersion int          `json:"schema_version"`
			ID            string       `json:"id"`
			Generation    uint64       `json:"generation"`
			RolloutID     string       `json:"rollout_id"`
			Scope         *trust.Scope `json:"scope"`
			Unit          string       `json:"unit"`
			OperationID   string       `json:"operation_id"`
		}
		if err := protocol.DecodeTolerant(entry.Value(), &kind, maxRecordBytes); err != nil {
			return nil, err
		}
		step := kind.Scope != nil && kind.Scope.Slot != "" && key == entityid.Derive("rollout-step", kind.Scope.Slot)
		reply := kind.Unit != "" && entityid.Valid(kind.OperationID) && key == entityid.Derive("rollout-step-reply", kind.Unit)
		marker, err := decodeAbandoned(entry.Value(), key)
		if err != nil {
			return nil, err
		}
		abandoned := marker != nil
		joined := kind.Node != "" && kind.PublicKey != "" && key == HostMembershipKey(kind.Node)
		if kind.ID == "" && kind.Generation == 0 && (kind.RolloutID == key || step || reply || abandoned || joined) {
			continue
		}
		var release Release
		if err := protocol.DecodeTolerant(entry.Value(), &release, maxRecordBytes); err != nil {
			return nil, err
		}
		if err := release.validate(); err != nil || generationKey(s.cell, release.Generation) != key || release.ID != key {
			return nil, fmt.Errorf("%w: stored generation key %q", ErrInvalid, key)
		}
		releases = append(releases, release)
	}
	return releases, nil
}

// ReleasePins returns every retained rollback generation and every durable
// known-bad digest, including entries aged out of the bounded cell list.
func (s *Store) ReleasePins(ctx context.Context) (rollback, knownBad []string, err error) {
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return nil, nil, err
		}
		rollback, knownBad, err := s.collectReleasePins(ctx, desired)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			// A purge can follow the desired write without changing its revision.
			continue
		}
		if err != nil {
			return nil, nil, err
		}
		_, observedRevision, err := s.Desired(ctx)
		if err != nil {
			return nil, nil, err
		}
		// Publication can retain and prune generations during the inventory.
		if observedRevision == revision {
			return rollback, knownBad, nil
		}
	}
	return nil, nil, ErrConflict
}

func (s *Store) collectReleasePins(ctx context.Context, desired Desired) (rollback, knownBad []string, err error) {
	releases, err := s.retainedReleases(ctx, desired)
	if err != nil {
		return nil, nil, err
	}
	for _, release := range releases {
		rollback = append(rollback, release.Digest)
	}
	state, _, err := s.Cell(ctx)
	if err != nil {
		return nil, nil, err
	}
	knownBad = slices.Clone(state.KnownBad)
	keys, err := releasechannel.PinKeys(ctx, s.kv, "knownbad.*")
	if err != nil {
		return nil, nil, err
	}
	for _, key := range keys {
		digest := strings.TrimPrefix(key, "knownbad.")
		if !digestRE.MatchString(digest) {
			return nil, nil, fmt.Errorf("%w: known-bad key %q", ErrInvalid, key)
		}
		knownBad = append(knownBad, digest)
	}
	// A rollout's predecessor may predate the retained generation window,
	// or be the image's baked binary, which has no generation of its own.
	if state.ActiveRolloutID != "" {
		record, _, active, err := s.Active(ctx)
		if err != nil {
			return nil, nil, err
		}
		if active {
			rollback = append(rollback, record.FromDigest)
			knownBad = append(knownBad, record.KnownBad...)
		}
	}
	slices.Sort(rollback)
	slices.Sort(knownBad)
	return slices.Compact(rollback), slices.Compact(knownBad), nil
}

sequence_guard.text:
func rejectSequencedReceipt(wire []byte) error {
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil || envelope.Scope.Domain != release.UpdateReceiptDomain {
		return nil
	}
	var receipt release.BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return err
	}
	if receipt.ReleaseSequence > 0 || receipt.SequenceMigrationSHA256 != "" {
		return fmt.Errorf("%w: signed sequence requires signature admission", ErrInvalid)
	}
	return nil
}

sequence_order.text:
func (s *Store) seedReleaseOrdering(ctx context.Context, desired Desired) (Desired, error) {
	if desired.OrderingFloor.Generation > 0 || desired.LegacyFloor.Generation > 0 && desired.LegacyIssuanceFloor.Generation > 0 || desired.Generation() == 0 {
		return desired, nil
	}
	retained, err := s.retainedReleases(ctx, desired)
	if err != nil {
		return Desired{}, err
	}
	for _, historical := range retained {
		if historical.ReleaseSequence > 0 {
			return Desired{}, fmt.Errorf("%w: sequenced history has no durable floor", ErrInvalid)
		}
		if desired.LegacyFloor.Generation == 0 || historical.RunNumber > desired.LegacyFloor.RunNumber {
			desired.LegacyFloor = historical
		}
		if desired.LegacyIssuanceFloor.Generation == 0 || historical.CreatedAt.After(desired.LegacyIssuanceFloor.CreatedAt) {
			desired.LegacyIssuanceFloor = historical
		}
	}
	return desired, nil
}

func advanceReleaseOrdering(desired *Desired, next Release, cell string) error {
	floor := desired.OrderingFloor
	if floor.ReleaseSequence > 0 {
		if next.SequenceMigrationSHA256 != floor.SequenceMigrationSHA256 {
			return fmt.Errorf("%w: release ordering migration cannot change", ErrInvalid)
		}
		if next.ReleaseSequence < floor.ReleaseSequence {
			return fmt.Errorf("%w: signer sequence %d is below retained floor %d", ErrInvalid, next.ReleaseSequence, floor.ReleaseSequence)
		}
		if next.ReleaseSequence == floor.ReleaseSequence {
			same, err := sameSequencedContent(floor, next)
			if err != nil {
				return err
			}
			if !same {
				return fmt.Errorf("%w: signer sequence already names another release", ErrInvalid)
			}
			if desired.Release.Digest != next.Digest || desired.Release.RollbackOf != 0 {
				return fmt.Errorf("%w: retained sequence cannot restart a rolled-back release", ErrInvalid)
			}
			return nil
		}
	}
	if next.ReleaseSequence > 0 {
		envelope, err := trust.DecodeEnvelope(next.SequenceMigration)
		if err != nil {
			return err
		}
		var migration release.SequenceMigration
		if err := protocol.DecodeStrict(envelope.Payload, &migration, trust.MaxPayloadBytes); err != nil {
			return err
		}
		if !migration.AdmitsLegacyFloor(strings.ToUpper(cell), desired.LegacyFloor.RunNumber, desired.LegacyIssuanceFloor.CreatedAt) {
			return fmt.Errorf("%w: migration omits retained legacy run floor %d", ErrInvalid, desired.LegacyFloor.RunNumber)
		}
		desired.OrderingFloor = next
	} else {
		if next.RunNumber < desired.LegacyFloor.RunNumber {
			return fmt.Errorf("%w: CI run is below retained legacy floor", ErrInvalid)
		}
		if next.CreatedAt.Before(desired.LegacyIssuanceFloor.CreatedAt) {
			return fmt.Errorf("%w: issuance is below retained legacy floor", ErrInvalid)
		}
		if next.RunNumber > 0 && next.RunNumber == desired.LegacyFloor.RunNumber && (next.Digest != desired.LegacyFloor.Digest || next.SourceRevision != desired.LegacyFloor.SourceRevision) {
			return fmt.Errorf("%w: CI run already names another release", ErrInvalid)
		}
		if desired.LegacyFloor.Generation == 0 || next.RunNumber > desired.LegacyFloor.RunNumber {
			desired.LegacyFloor = next
		}
		if desired.LegacyIssuanceFloor.Generation == 0 || next.CreatedAt.After(desired.LegacyIssuanceFloor.CreatedAt) {
			desired.LegacyIssuanceFloor = next
		}
	}
	return nil
}

func newerReleaseOrder(previous, next Release) bool {
	if previous.ReleaseSequence > 0 || next.ReleaseSequence > 0 {
		return next.ReleaseSequence > previous.ReleaseSequence
	}
	return next.RunNumber > previous.RunNumber
}

history.text:
func (s *Store) RecentRollouts(ctx context.Context) ([]insights.Rollout, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return nil, err
	}
	active, _, ok, err := s.Active(ctx)
	if err != nil {
		return nil, err
	}
	var records []insights.Rollout
	seen := make(map[string]bool)
	if ok {
		records = append(records, InsightRollout(active))
		seen[active.RolloutID] = true
	}
	newest := desired.Generation()
	for offset := range min(newest, uint64(ReleaseHistory)) {
		for _, domain := range []string{ControllerReleaseDomain, HostReleaseDomain} {
			if err := ctx.Err(); err != nil {
				return nil, err
			}
			id := entityid.Derive(domain, ReleaseRolloutID(newest-offset))
			if seen[id] {
				continue
			}
			record, _, err := s.Load(ctx, id)
			if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, ErrAbandonedRollout) {
				continue
			}
			if err != nil {
				return nil, err
			}
			records = append(records, InsightRollout(record))
			seen[id] = true
		}
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	slices.SortFunc(records, func(a, b insights.Rollout) int {
		return cmp.Or(b.PhaseStarted.Compare(a.PhaseStarted), cmp.Compare(a.ID, b.ID))
	})
	return records, nil
}

