decisions.text:
func transitionDecision(previous, next Record) (decisionlog.Kind, decisionlog.Status, string) {
	id := next.RolloutID
	switch next.Phase {
	case PhaseCanary:
		return decisionlog.KindUpgradeStarted, decisionlog.StatusInProgress, "Started canary of rollout " + id
	case PhaseBatch:
		if previous.Phase == PhaseCanarySoak {
			return decisionlog.KindCanaryPromoted, decisionlog.StatusInProgress, "Promoted the canary of rollout " + id
		}
		return decisionlog.KindBatchPromoted, decisionlog.StatusInProgress,
			fmt.Sprintf("Promoted wave %d of rollout %s", next.WaveIndex, id)
	case PhaseComplete:
		return decisionlog.KindRolloutCompleted, decisionlog.StatusSucceeded, "Completed rollout " + id
	case PhaseRollingBack:
		return decisionlog.KindRollback, decisionlog.StatusInProgress, "Rolling back rollout " + id
	case PhaseRolledBack:
		return decisionlog.KindRollback, decisionlog.StatusRolledBack, "Rolled back rollout " + id
	case PhaseFrozen:
		return decisionlog.KindFrozen, decisionlog.StatusPending, "Froze rollout " + id + " for operator review"
	case PhaseAborted:
		return decisionlog.KindHeld, decisionlog.StatusFailed, "Aborted rollout " + id
	}
	return "", "", ""
}

// Rollouts lists the cell's active rollout for the insight engine's deadline
// rule. It implements insights.RolloutProvider.
func (s *Store) Rollouts(ctx context.Context) ([]insights.Rollout, error) {
	record, _, active, err := s.Active(ctx)
	if err != nil || !active {
		return nil, err
	}
	return []insights.Rollout{InsightRollout(record)}, nil
}

// InsightRollout is the insight view of one rollout record.
func InsightRollout(record Record) insights.Rollout {
	return insights.Rollout{ID: record.RolloutID, Release: record.ToDigest, Phase: string(record.Phase),
		PhaseStarted: record.PhaseStartedAt, PhaseDeadline: record.PhaseDeadline, Done: record.Phase.Terminal()}
}

new_apply.text:
func New(spec Spec, now time.Time) (Record, error) {
	if now.IsZero() || spec.StartedAt.After(now) {
		return Record{}, fmt.Errorf("%w: start time", ErrInvalid)
	}
	if slices.Contains(spec.KnownBad, spec.ToDigest) {
		return Record{}, ErrKnownBad
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return Record{}, err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return Record{}, err
	}
	units := make(map[string]UnitProgress, len(spec.Units))
	for _, unit := range spec.Units {
		units[unit.ID] = UnitProgress{State: UnitPending, Group: unit.Group, Seed: unit.Seed}
	}
	for wave, ids := range waves {
		for _, id := range ids {
			progress := units[id]
			progress.Wave = wave
			units[id] = progress
		}
	}
	knownBad := slices.Clone(spec.KnownBad)
	slices.Sort(knownBad)
	started := spec.StartedAt
	if started.IsZero() {
		started = now
	}
	record := Record{
		SchemaVersion: SchemaVersion, RolloutID: spec.RolloutID, Kind: spec.Kind, Cell: spec.Cell,
		FromDigest: spec.FromDigest, ToDigest: spec.ToDigest, Policy: spec.Policy, PolicyDigest: policyDigest,
		Phase: PhasePending, Waves: waves, Units: units, KnownBad: slices.Compact(knownBad),
		StartedAt: started.UTC(), PhaseStartedAt: now.UTC(), AuthorityEpoch: spec.AuthorityEpoch,
	}
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	return record, nil
}

apply.text:
func Apply(record Record, event Event) (Record, error) {
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	if event.At.IsZero() || len(event.Reason) > maxReason {
		return Record{}, fmt.Errorf("%w: event time or reason", ErrInvalid)
	}
	if record.Phase.Terminal() {
		return Record{}, ErrTerminal
	}
	next := record.Clone()
	at := event.At.UTC()
	if completionEvent(event.Kind) || event.Kind == EventStart {
		// A completion that arrives after its phase deadline must not erase
		// that deadline: enforce it first, exactly as a tick at the same
		// instant would, and drop the late completion if it fired.
		phase, wave := next.Phase, next.WaveIndex
		next.tick(at)
		if next.Phase != phase || next.WaveIndex != wave {
			if err := next.Validate(); err != nil {
				return Record{}, err
			}
			return next, nil
		}
	}
	var err error
	switch event.Kind {
	case EventStart:
		err = next.start(at)
	case EventPreflightPassed:
		err = next.preflightPassed(at)
	case EventPreflightFailed:
		err = next.requirePhase(PhasePreflight)
		if err == nil {
			next.finish(PhaseAborted, at, reasonOr(event.Reason, "preflight failed"))
		}
	case EventPrepared:
		err = next.prepared(event.Unit, at)
	case EventHealthy:
		err = next.healthy(event.Unit, event.Health, at)
	case EventUnhealthy, EventHeld:
		// A held forward step rolls back like an unhealthy one; rollback
		// itself, not the forward unit, is what freezes for a human.
		err = next.failed(event.Unit, at, reasonOr(event.Reason, string(event.Kind)))
	case EventRollbackServing:
		err = next.rollbackServing(event.Unit, at)
	case EventRollbackHeld:
		err = next.rollbackHeld(event.Unit, at, reasonOr(event.Reason, "rollback held"))
	case EventTick:
		next.tick(at)
	case EventAbort:
		err = next.abort(at, reasonOr(event.Reason, "operator abort"))
	case EventFreeze:
		if next.Phase == PhaseFrozen {
			return Record{}, ErrInvalidTransition
		}
		next.enter(PhaseFrozen, at, time.Time{}, reasonOr(event.Reason, "frozen"))
	case EventResume:
		err = next.resume(at, event.Left)
	default:
		err = fmt.Errorf("%w: event kind", ErrInvalid)
	}
	if err != nil {
		return Record{}, err
	}
	if err := next.Validate(); err != nil {
		return Record{}, err
	}
	return next, nil
}

// completionEvent reports events that complete a phase with a deadline.
func completionEvent(kind EventKind) bool {
	return kind == EventPreflightPassed || kind == EventPrepared || kind == EventHealthy
}

// boundReason keeps a stored reason within maxReason bytes without splitting
// a UTF-8 rune, so a prefixed failure reason can never fail validation and
// discard the rollback it describes.
func boundReason(reason string) string {
	if len(reason) <= maxReason {
		return reason
	}
	const ellipsis = "..."
	cut := maxReason - len(ellipsis)
	for cut > 0 && !utf8.RuneStart(reason[cut]) {
		cut--
	}
	return reason[:cut] + ellipsis
}

func reasonOr(reason, fallback string) string {
	if reason == "" {
		return fallback
	}
	return reason
}

func (record *Record) requirePhase(phases ...Phase) error {
	if !slices.Contains(phases, record.Phase) {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	return nil
}

forward.text:
func (record *Record) enter(phase Phase, at, deadline time.Time, reason string) {
	if (phase == PhasePreflight || phase.preparing() || phase.soaking()) && deadline.After(record.StartedAt.Add(ObservationBudget)) {
		deadline = record.StartedAt.Add(ObservationBudget)
	}
	record.Phase = phase
	record.PhaseStartedAt = at
	record.PhaseDeadline = deadline
	record.Reason = boundReason(reason)
}

func (record *Record) finish(phase Phase, at time.Time, reason string) {
	record.enter(phase, at, time.Time{}, reason)
}

func (record *Record) start(at time.Time) error {
	if err := record.requirePhase(PhasePending); err != nil {
		return err
	}
	if slices.Contains(record.KnownBad, record.ToDigest) {
		record.finish(PhaseAborted, at, "target digest is known bad")
		return nil
	}
	record.enter(PhasePreflight, at, at.Add(seconds(record.Policy.PreflightSeconds)), "")
	return nil
}

func (record *Record) preflightPassed(at time.Time) error {
	if err := record.requirePhase(PhasePreflight); err != nil {
		return err
	}
	if slices.Contains(record.KnownBad, record.ToDigest) {
		record.finish(PhaseAborted, at, "target digest is known bad")
		return nil
	}
	record.beginWave(0, at)
	return nil
}

// beginWave marks the wave's units as preparing. The executor must only
// issue each prepare after the unit's group peers are serving (see Action).
func (record *Record) beginWave(wave int, at time.Time) {
	record.WaveIndex = wave
	phase := PhaseBatch
	if wave == 0 {
		phase = PhaseCanary
	}
	for _, id := range record.Waves[wave] {
		progress := record.Units[id]
		progress.State = UnitPreparing
		progress.HealthyReports, progress.FirstHealthyAt, progress.ProcessID, progress.StartNonce = 0, time.Time{}, 0, ""
		progress.LastHealthyAt = time.Time{}
		record.Units[id] = progress
	}
	record.enter(phase, at, at.Add(seconds(record.Policy.ProofDeadlineSeconds)), "")
}

func (record *Record) currentWaveUnit(unit string) (UnitProgress, error) {
	progress, exists := record.Units[unit]
	if !exists || progress.Wave != record.WaveIndex {
		return UnitProgress{}, fmt.Errorf("%w: unit %q is not in the current wave", ErrInvalidTransition, unit)
	}
	return progress, nil
}

func (record *Record) prepared(unit string, at time.Time) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, err := record.currentWaveUnit(unit)
	if err != nil {
		return err
	}
	switch progress.State {
	case UnitSoaking:
		return nil
	case UnitPreparing:
	default:
		return fmt.Errorf("%w: unit %q is %s", ErrInvalidTransition, unit, progress.State)
	}
	progress.State = UnitSoaking
	record.Units[unit] = progress
	if record.Phase.preparing() && record.waveState(UnitSoaking) {
		phase := PhaseBatchSoak
		if record.Phase == PhaseCanary {
			phase = PhaseCanarySoak
		}
		record.enter(phase, at, at.Add(seconds(record.Policy.ProofDeadlineSeconds)), "")
	}
	return nil
}

func (record *Record) waveState(state UnitState) bool {
	for _, id := range record.Waves[record.WaveIndex] {
		if record.Units[id].State != state {
			return false
		}
	}
	return true
}

func (record *Record) healthy(unit string, health Health, at time.Time) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, err := record.currentWaveUnit(unit)
	if err != nil {
		return err
	}
	if progress.State != UnitSoaking {
		return fmt.Errorf("%w: unit %q is %s", ErrInvalidTransition, unit, progress.State)
	}
	if health.ProcessID <= 0 || !nonceRE.MatchString(health.StartNonce) || health.ObservedAt.IsZero() {
		return fmt.Errorf("%w: health report identity", ErrInvalid)
	}
	if health.ObservedAt.Before(record.PhaseStartedAt) || health.ObservedAt.After(at.Add(time.Minute)) {
		// A report older than the current phase cannot prove the new
		// process, in the preparing phase as little as in the soak: a
		// replayed report would start the soak clock in the past.
		return fmt.Errorf("%w: stale or future health report", ErrInvalid)
	}
	if health.Digest != record.ToDigest {
		record.startRollback(at, fmt.Sprintf("unit %s serves an unexpected digest", unit))
		return nil
	}
	if progress.HealthyReports > 0 && (progress.ProcessID != health.ProcessID || progress.StartNonce != health.StartNonce) {
		record.startRollback(at, fmt.Sprintf("unit %s restarted during soak", unit))
		return nil
	}
	observed := health.ObservedAt.UTC()
	if progress.HealthyReports > 0 && !observed.After(progress.LastHealthyAt) {
		// A replayed or reordered report proves nothing new.
		return nil
	}
	if progress.HealthyReports == 0 {
		progress.FirstHealthyAt = observed
		progress.ProcessID, progress.StartNonce = health.ProcessID, health.StartNonce
	}
	progress.LastHealthyAt = observed
	progress.HealthyReports++
	record.Units[unit] = progress
	record.advanceIfSoaked(at)
	return nil
}

rollback.text:
func (record *Record) soakDuration() time.Duration {
	if record.Phase == PhaseCanarySoak {
		return seconds(record.Policy.CanarySoakSeconds)
	}
	return seconds(record.Policy.BatchSoakSeconds)
}

// advanceIfSoaked promotes the wave once every unit has produced the
// required consecutive reports from one incarnation over the soak window.
func (record *Record) advanceIfSoaked(at time.Time) {
	if !record.Phase.soaking() {
		return
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		// The observations, not elapsed tick time, must span the window: a
		// unit that stopped reporting early never completes its soak.
		if progress.State != UnitSoaking || progress.HealthyReports < record.Policy.MinHealthyReports ||
			progress.LastHealthyAt.Before(progress.FirstHealthyAt.Add(record.soakDuration())) {
			return
		}
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		progress.State = UnitPromoted
		record.Units[id] = progress
	}
	if record.WaveIndex+1 < len(record.Waves) {
		record.beginWave(record.WaveIndex+1, at)
		return
	}
	record.finish(PhaseComplete, at, "")
}

func (record *Record) tick(at time.Time) {
	if (record.Phase == PhasePending || record.Phase == PhasePreflight || record.Phase.preparing() || record.Phase.soaking()) &&
		!at.Before(record.StartedAt.Add(ObservationBudget)) {
		reason := "release exceeded its fixed 20-minute observation budget"
		if record.Phase == PhasePending || record.Phase == PhasePreflight {
			record.finish(PhaseAborted, at, reason)
		} else {
			record.startRollback(at, reason)
		}
		return
	}
	switch {
	case record.Phase == PhasePreflight && !at.Before(record.PhaseDeadline):
		record.finish(PhaseAborted, at, "preflight deadline exceeded")
	case record.Phase.preparing() && !at.Before(record.PhaseDeadline):
		record.startRollback(at, "prepare deadline exceeded")
	case record.Phase.soaking():
		if !at.Before(record.PhaseDeadline) {
			for _, id := range record.Waves[record.WaveIndex] {
				if record.Units[id].HealthyReports == 0 {
					record.startRollback(at, fmt.Sprintf("unit %s missed its serving-proof deadline", id))
					return
				}
			}
		}
		wave := record.WaveIndex
		record.advanceIfSoaked(at)
		// Every unit that proved itself before the serving-proof deadline
		// has finished its soak window by deadline+soak, and has reported
		// again within minSoakGap after it. A wave still soaking then has a
		// unit that stopped reporting (for example a hung process after one
		// healthy report); it must not hold the cell's rollout slot forever.
		if record.Phase.soaking() && record.WaveIndex == wave &&
			!at.Before(record.PhaseDeadline.Add(record.soakDuration()).Add(minSoakGap)) {
			record.startRollback(at, "soak did not complete before its deadline")
		}
	case record.Phase == PhaseRollingBack && !at.Before(record.PhaseDeadline):
		head := record.rollbackHead()
		if head != "" {
			progress := record.Units[head]
			progress.State = UnitHeld
			record.Units[head] = progress
		}
		record.enter(PhaseFrozen, at, time.Time{}, "rollback deadline exceeded")
	}
}

// startRollback durably marks ToDigest known bad in the same record write
// that first orders any rollback action, then rolls back every touched unit
// newest first.
func (record *Record) startRollback(at time.Time, reason string) {
	if !slices.Contains(record.KnownBad, record.ToDigest) {
		record.KnownBad = append(record.KnownBad, record.ToDigest)
		slices.Sort(record.KnownBad)
		if len(record.KnownBad) > MaxKnownBad {
			// Keep the current target; the cell list retains the dropped entry.
			drop := 0
			if record.KnownBad[0] == record.ToDigest {
				drop = 1
			}
			record.KnownBad = slices.Delete(record.KnownBad, drop, drop+1)
		}
	}
	var touched []string
	for id, progress := range record.Units {
		if progress.State.touched() {
			touched = append(touched, id)
		}
	}
	slices.SortFunc(touched, func(a, b string) int {
		if order := cmp.Compare(record.Units[b].Wave, record.Units[a].Wave); order != 0 {
			return order
		}
		return cmp.Compare(b, a)
	})
	for _, id := range touched {
		progress := record.Units[id]
		progress.State = UnitRollingBack
		record.Units[id] = progress
	}
	record.RollbackOrder = touched
	if len(touched) == 0 {
		record.finish(PhaseRolledBack, at, reason)
		return
	}
	record.enter(PhaseRollingBack, at, at.Add(seconds(record.Policy.RollbackDeadlineSeconds)), reason)
}

// rollbackHead returns the next unit to return to FromDigest. Rollback moves
// one unit at a time so the group peer of each step keeps serving.
func (record *Record) rollbackHead() string {
	for _, id := range record.RollbackOrder {
		if record.Units[id].State == UnitRollingBack {
			return id
		}
	}
	return ""
}

abort.text:
func (record *Record) abort(at time.Time, reason string) error {
	switch {
	case record.Phase == PhasePending || record.Phase == PhasePreflight:
		record.finish(PhaseAborted, at, reason)
	case record.Phase.preparing() || record.Phase.soaking():
		record.startRollback(at, reason)
	default:
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	return nil
}

phase_policy.text:
// Terminal reports whether no further transition can change the record.
func (phase Phase) Terminal() bool {
	return phase == PhaseComplete || phase == PhaseAborted || phase == PhaseRolledBack
}

// Active reports whether the phase holds the cell's single rollout slot.
func (phase Phase) Active() bool { return !phase.Terminal() }

func (phase Phase) preparing() bool { return phase == PhaseCanary || phase == PhaseBatch }
func (phase Phase) soaking() bool   { return phase == PhaseCanarySoak || phase == PhaseBatchSoak }

// UnitState is the per-unit progress recorded in the rollout.
type UnitState string

const (
	UnitPending     UnitState = "pending"
	UnitPreparing   UnitState = "preparing"
	UnitSoaking     UnitState = "soaking"
	UnitPromoted    UnitState = "promoted"
	UnitRollingBack UnitState = "rolling-back"
	UnitRolledBack  UnitState = "rolled-back"
	UnitHeld        UnitState = "held"
)

// touched reports whether the unit may run the target digest and therefore
// needs an explicit rollback.
func (state UnitState) touched() bool {
	return state == UnitPreparing || state == UnitSoaking || state == UnitPromoted ||
		state == UnitRollingBack || state == UnitHeld
}

policy.text:
// QualificationBudget and ObservationBudget share the fixed release window.
// Rollback has its own recovery deadline and never consumes this budget.
const (
	QualificationBudget = 10 * time.Minute
	ObservationBudget   = 20 * time.Minute
)

// DefaultPolicy is as fast as a binary-only update allows (user decision
// 2026-10-06): one canary soaks five minutes, then every later wave takes as
// many units as PlanWaves lets it (never two of one group, the seed last and
// alone, so three controllers still move one at a time) and soaks two
// minutes. A unit that restarts on another release, or does not prove the
// target within ten minutes, rolls the rollout back.
func DefaultPolicy() Policy {
	return Policy{
		CanaryUnits: 1, BatchSize: MaxUnits,
		CanarySoakSeconds: int64((5 * time.Minute).Seconds()), BatchSoakSeconds: int64((2 * time.Minute).Seconds()),
		MinHealthyReports: 3, ProofDeadlineSeconds: int64((10 * time.Minute).Seconds()),
		RollbackDeadlineSeconds: int64((10 * time.Minute).Seconds()), PreflightSeconds: int64((10 * time.Minute).Seconds()),
		MaxAttempts: 1, MaxRollbackRetries: 3,
	}
}

// Validate rejects policies that could skip the canary, soak or deadlines.
func (policy Policy) Validate() error {
	if policy.CanaryUnits < 1 || policy.CanaryUnits > MaxUnits || policy.BatchSize < 1 || policy.BatchSize > MaxUnits ||
		policy.CanarySoakSeconds < 0 || policy.BatchSoakSeconds < 0 || policy.MinHealthyReports < 1 ||
		policy.ProofDeadlineSeconds < 1 || policy.RollbackDeadlineSeconds < 1 || policy.PreflightSeconds < 1 ||
		policy.MaxAttempts < 1 || policy.MaxRollbackRetries < 0 {
		return fmt.Errorf("%w: policy bounds", ErrInvalid)
	}
	return nil
}

// Digest is SHA-256 of the canonical policy encoding.
func (policy Policy) Digest() (string, error) {
	encoded, err := protocol.EncodeJSON(policy)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(encoded)
	return hex.EncodeToString(sum[:]), nil
}

validation.text:
func (record Record) Validate() error {
	if record.SchemaVersion != SchemaVersion || !entityid.Valid(record.RolloutID) || !record.Kind.valid() ||
		!tokenRE.MatchString(record.Cell) || !digestRE.MatchString(record.FromDigest) || !digestRE.MatchString(record.ToDigest) ||
		record.FromDigest == record.ToDigest || record.AuthorityEpoch == 0 || record.StartedAt.IsZero() ||
		record.PhaseStartedAt.IsZero() || len(record.Reason) > maxReason || len(record.KnownBad) > MaxKnownBad {
		return fmt.Errorf("%w: record identity", ErrInvalid)
	}
	if err := record.Policy.Validate(); err != nil {
		return err
	}
	if digest, err := record.Policy.Digest(); err != nil || digest != record.PolicyDigest {
		return fmt.Errorf("%w: policy digest", ErrInvalid)
	}
	switch record.Phase {
	case PhasePending, PhasePreflight, PhaseCanary, PhaseCanarySoak, PhaseBatch, PhaseBatchSoak,
		PhaseComplete, PhaseRollingBack, PhaseFrozen, PhaseAborted, PhaseRolledBack:
	default:
		return fmt.Errorf("%w: phase", ErrInvalid)
	}
	if len(record.Waves) == 0 || len(record.Units) == 0 || len(record.Units) > MaxUnits ||
		record.WaveIndex < 0 || record.WaveIndex >= len(record.Waves) {
		return fmt.Errorf("%w: waves", ErrInvalid)
	}
	seen := make(map[string]struct{}, len(record.Units))
	for wave, ids := range record.Waves {
		if len(ids) == 0 {
			return fmt.Errorf("%w: empty wave", ErrInvalid)
		}
		for _, id := range ids {
			progress, exists := record.Units[id]
			if _, duplicate := seen[id]; duplicate || !exists || progress.Wave != wave || !tokenRE.MatchString(progress.Group) {
				return fmt.Errorf("%w: wave unit %q", ErrInvalid, id)
			}
			seen[id] = struct{}{}
		}
	}
	if len(seen) != len(record.Units) {
		return fmt.Errorf("%w: unit outside every wave", ErrInvalid)
	}
	for _, id := range record.RollbackOrder {
		if _, exists := record.Units[id]; !exists {
			return fmt.Errorf("%w: rollback unit %q", ErrInvalid, id)
		}
	}
	for _, digest := range record.KnownBad {
		if !digestRE.MatchString(digest) {
			return fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
	}
	if slices.Contains(record.KnownBad, record.FromDigest) {
		return fmt.Errorf("%w: rollback target is known bad", ErrInvalid)
	}
	return record.validatePhaseUnits()
}

// validatePhaseUnits rejects phase and unit-state contradictions that Apply
// never produces, so a record built outside Apply is refused at the storage
// boundary instead of driving effects.
func (record Record) validatePhaseUnits() error {
	for _, id := range record.Waves[record.WaveIndex] {
		state := record.Units[id].State
		if record.Phase.soaking() && state != UnitSoaking ||
			record.Phase.preparing() && state != UnitPreparing && state != UnitSoaking {
			return fmt.Errorf("%w: phase %s contradicts unit %q in state %s", ErrInvalid, record.Phase, id, state)
		}
	}
	if record.Phase == PhaseRollingBack && record.rollbackHead() == "" {
		return fmt.Errorf("%w: rolling back without a unit to roll back", ErrInvalid)
	}
	return nil
}

func (record Record) abortedBeforeUpdate() bool {
	if record.Phase != PhaseAborted || len(record.RollbackOrder) != 0 {
		return false
	}
	for _, progress := range record.Units {
		if progress.State != UnitPending {
			return false
		}
	}
	return true
}

// Clone returns a deep copy so transitions never alias a caller's record.
func (record Record) Clone() Record {
	clone := record
	clone.Waves = make([][]string, len(record.Waves))
	for index, wave := range record.Waves {
		clone.Waves[index] = slices.Clone(wave)
	}
	clone.Units = make(map[string]UnitProgress, len(record.Units))
	for id, progress := range record.Units {
		clone.Units[id] = progress
	}
	clone.RollbackOrder = slices.Clone(record.RollbackOrder)
	clone.KnownBad = slices.Clone(record.KnownBad)
	return clone
}

actions.text:
func NextActions(record Record) []Action {
	if record.Validate() != nil {
		return nil
	}
	switch {
	case record.Phase == PhasePreflight:
		return []Action{{Kind: ActionPreflight, Deadline: record.PhaseDeadline}}
	case record.Phase.preparing() || record.Phase.soaking():
		var actions []Action
		for _, id := range record.Waves[record.WaveIndex] {
			progress := record.Units[id]
			switch progress.State {
			case UnitPreparing:
				actions = append(actions, Action{
					Kind: ActionPrepare, Unit: id, Digest: record.ToDigest,
					OperationID: OperationID(record.RolloutID, id, record.Phase, progress.Attempts),
					Peers:       record.peers(id), Deadline: record.PhaseDeadline,
				})
			case UnitSoaking:
				actions = append(actions, Action{Kind: ActionAwaitHealth, Unit: id, Digest: record.ToDigest, Deadline: record.PhaseDeadline})
			}
		}
		return actions
	case record.Phase == PhaseRollingBack:
		head := record.rollbackHead()
		if head == "" {
			return nil
		}
		return []Action{{
			Kind: ActionRollback, Unit: head, Digest: record.FromDigest,
			OperationID: OperationID(record.RolloutID, head, PhaseRollingBack, record.Units[head].Attempts),
			Peers:       record.peers(head), Deadline: record.PhaseDeadline,
		}}
	case record.Phase == PhaseFrozen:
		return []Action{{Kind: ActionPage}}
	}
	return nil
}

// peers lists the other units of id's group. A step may only start while
// they are serving, which keeps the group above quorum.
func (record Record) peers(id string) []string {
	group := record.Units[id].Group
	var peers []string
	for other, progress := range record.Units {
		if other != id && progress.Group == group {
			peers = append(peers, other)
		}
	}
	slices.Sort(peers)
	return peers
}

plan.text:
func PlanWaves(units []Unit, policy Policy) ([][]string, error) {
	if err := policy.Validate(); err != nil {
		return nil, err
	}
	if len(units) == 0 || len(units) > MaxUnits {
		return nil, fmt.Errorf("%w: unit count", ErrInvalid)
	}
	ordered := slices.Clone(units)
	slices.SortFunc(ordered, func(a, b Unit) int { return cmp.Compare(a.ID, b.ID) })
	var seeds, rest []Unit
	seen := make(map[string]struct{}, len(ordered))
	for _, unit := range ordered {
		if !tokenRE.MatchString(unit.ID) || !tokenRE.MatchString(unit.Group) {
			return nil, fmt.Errorf("%w: unit identity %q", ErrInvalid, unit.ID)
		}
		if _, duplicate := seen[unit.ID]; duplicate {
			return nil, fmt.Errorf("%w: duplicate unit %q", ErrInvalid, unit.ID)
		}
		seen[unit.ID] = struct{}{}
		if unit.Seed {
			seeds = append(seeds, unit)
		} else {
			rest = append(rest, unit)
		}
	}
	if len(seeds) > 1 {
		return nil, fmt.Errorf("%w: more than one seed unit", ErrInvalid)
	}
	var waves [][]string
	first := true
	for len(rest) > 0 {
		limit := policy.BatchSize
		if first {
			limit = policy.CanaryUnits
		}
		wave, remaining := takeWave(rest, limit)
		waves = append(waves, wave)
		rest = remaining
		first = false
	}
	for _, seed := range seeds {
		waves = append(waves, []string{seed.ID})
	}
	return waves, nil
}

// takeWave greedily selects up to limit units with pairwise distinct groups,
// preserving order for the units it leaves behind.
func takeWave(units []Unit, limit int) ([]string, []Unit) {
	groups := map[string]struct{}{}
	var wave []string
	var remaining []Unit
	for _, unit := range units {
		if _, taken := groups[unit.Group]; len(wave) < limit && !taken {
			groups[unit.Group] = struct{}{}
			wave = append(wave, unit.ID)
			continue
		}
		remaining = append(remaining, unit)
	}
	return wave, remaining
}

